using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// Options with the default reflection-based resolver (resolves any type)
var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);

// 1. GetTypeInfo<T>() — returns a strongly-typed JsonTypeInfo<T>
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"GetTypeInfo<Person> succeeded — Type: {personInfo.Type.Name}");

string json = JsonSerializer.Serialize(new Person("Alice", 42), personInfo);
Console.WriteLine($"Serialized: {json}");

// 2. TryGetTypeInfo<T>() — probe without throwing
if (options.TryGetTypeInfo<Person>(out JsonTypeInfo<Person>? info))
{
    Console.WriteLine($"TryGetTypeInfo<Person> returned true — Type: {info!.Type.Name}");
}

// Now demonstrate the "not available" path using a custom resolver that only
// knows about Person, so probing for int[] will return false.
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = new LimitedResolver()
};

if (limited.TryGetTypeInfo<int[]>(out _))
{
    Console.WriteLine("TryGetTypeInfo<int[]> returned true (unexpected)");
}
else
{
    Console.WriteLine("TryGetTypeInfo<int[]> returned false — metadata not available");
}

// --- Supporting types ---

public record Person(string Name, int Age);

/// A resolver that only provides metadata for Person.
internal sealed class LimitedResolver : IJsonTypeInfoResolver
{
    private static readonly DefaultJsonTypeInfoResolver _inner = new();

    public JsonTypeInfo? GetTypeInfo(Type type, JsonSerializerOptions options)
    {
        if (type == typeof(Person))
            return _inner.GetTypeInfo(type, options);

        return null; // signal "not available"
    }
}

